75: * `bone` (a chain, or a list of chains and joints the body runs through) skins it as one mesh bending at each joint.
76: */
77:export function loft(ctx: Ctx, stations: readonly Station[], options: SweepOptions = {}) {
78:  const path = catmull(stations.map((s) => s.at));
79:  const ts = path.knots;
80:  const ws = stations.map((s) => s.w / 2);
81:  const hs = stations.map((s) => s.h / 2);
82:  return sweep(ctx, path, (t) => [interpolate(ts, ws, t), interpolate(ts, hs, t)], options);
