86:  Pick<ChainOptions, "names" | "twist" | "role" | "contact"> & {
87:    /** Joints along the appendage (default: one per knot span); 0 = no joints, the tube rides on the root's bone. */
88:    count?: number;
89:    /** How far the root runs back into the parent volume, along the start tangent (default: the root radius). */
90:    bury?: number;
91:  };
