95: * part, a joint. `pathOrTip` is a tip point (straight out) or a path (prefixed with the frame's point when it starts
96: * elsewhere). The first joint sits at the frame's point, parented to its bone (else the nearest joint); the tube's
97: * root continues `bury` back into the parent so it never floats. A single joint takes the sprout's own name.
98: */
99:export function sprout(
100:  ctx: Ctx,
101:  name: string,
102:  on: FrameInput,
103:  pathOrTip: PathInput | PointInput,
104:  radius: Radius,
105:  options: SproutOptions = {},
106:) {
107:  const { count, bury, names, role, contact, ...rest } = options;
108:  const root = toFrame(on, "sprout()");
109:  const start = root.at;
110:  const parent = boneFor(ctx, undefined, [root], start);
111:  const isPath =
112:    pathOrTip instanceof Path ||
113:    (Array.isArray(pathOrTip) ? typeof pathOrTip[0] !== "number" : "curve" in (pathOrTip as object));
114:  const given = isPath
115:    ? toPath(pathOrTip as PathInput)
116:    : polyline([start, toPoint(pathOrTip as PointInput, "sprout()")]);
117:  const path = given.at(0).distanceTo(start) > 1e-6 ? polyline([start, given.at(0)]).concat(given) : given;
118:  const joints = count ?? path.knots.length - 1;
119:  const chain =
120:    count === 0
121:      ? null
122:      : createChain(ctx, name, path, {
123:          parent,
124:          count,
125:          names: names ?? (joints === 1 ? [name] : undefined),
126:          role,
127:          contact,
128:          twist: rest.twist,
129:          up: rest.up,
130:          group: rest.group,
131:        });
132:  const sweepOptions = {
133:    name,
134:    ...rest,
135:    bone: parent,
136:    extend: [bury ?? Math.max(...radiusFn(radius)(0)), 0] as const,
137:  };
138:  return { chain, sweep: sweep(ctx, chain ?? path, radius, sweepOptions) };
139:}

